#include <stdio.h>

int main(void) {
    int n;
    long long a, best = 0, second = 0;
    int has_best = 0, has_second = 0;
    if (scanf("%d", &n) != 1) { printf("NONE\n"); return 0; }
    for (int i = 0; i < n; i++) {
        if (scanf("%lld", &a) != 1) break;
        if (!has_best || a > best) {
            if (has_best) { second = best; has_second = 1; }
            best = a; has_best = 1;
        } else if (a < best && (!has_second || a > second)) {
            second = a; has_second = 1;
        }
    }
    if (has_second) printf("%lld\n", second); else printf("NONE\n");
    return 0;
}

#include <iostream>
#include <set>

int main() {
    int n = 0;
    std::set<long long> values;
    if (!(std::cin >> n)) { std::cout << "NONE" << std::endl; return 0; }
    for (int i = 0; i < n; i++) { long long x; if (!(std::cin >> x)) break; values.insert(x); }
    if (values.size() < 2) { std::cout << "NONE" << std::endl; return 0; }
    auto it = values.end(); --it; --it;
    std::cout << *it << std::endl;
    return 0;
}

