#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAXL 1100
static char keys[200][MAXL], vals[200][MAXL];
static int cnt = 0;

static void trim(char *s) {
    size_t n = strlen(s);
    while (n && isspace((unsigned char)s[n - 1])) s[--n] = 0;
    size_t i = 0;
    while (s[i] && isspace((unsigned char)s[i])) i++;
    memmove(s, s + i, strlen(s + i) + 1);
}

static void lower(char *s) { for (; *s; s++) *s = (char)tolower((unsigned char)*s); }

int main(void) {
    char line[MAXL], k[MAXL], v[MAXL], q[MAXL] = "";
    if (!fgets(line, sizeof line, stdin)) return 0;
    int n = atoi(line);
    for (int i = 0; i < n; i++) {
        if (!fgets(line, sizeof line, stdin)) break;
        trim(line);
        if (!line[0] || line[0] == '#') continue;
        char *eq = strchr(line, '=');
        if (!eq) continue;
        *eq = 0;
        strcpy(k, line); strcpy(v, eq + 1);
        trim(k); trim(v); lower(k);
        size_t vl = strlen(v);
        if (vl >= 2 && v[0] == '"' && v[vl - 1] == '"') { v[vl - 1] = 0; memmove(v, v + 1, vl - 1); }
        int j;
        for (j = 0; j < cnt; j++) if (!strcmp(keys[j], k)) break;
        if (j == cnt) { strcpy(keys[cnt], k); cnt++; }
        strcpy(vals[j], v);
    }
    if (fgets(q, sizeof q, stdin)) { trim(q); lower(q); }
    for (int j = 0; j < cnt; j++) if (!strcmp(keys[j], q)) { printf("%s\n", vals[j]); return 0; }
    printf("MISSING\n");
    return 0;
}

#include <iostream>
#include <map>
#include <string>
#include <cctype>
using namespace std;

static string trim(const string &s) {
    size_t a = s.find_first_not_of(" \t\r\n");
    if (a == string::npos) return "";
    size_t b = s.find_last_not_of(" \t\r\n");
    return s.substr(a, b - a + 1);
}

int main() {
    string line;
    if (!getline(cin, line)) return 0;
    int n = stoi(trim(line));
    map<string, string> m;
    for (int i = 0; i < n && getline(cin, line); i++) {
        string s = trim(line);
        if (s.empty() || s[0] == '#') continue;
        size_t e = s.find('=');
        if (e == string::npos) continue;
        string k = trim(s.substr(0, e)), v = trim(s.substr(e + 1));
        for (auto &c : k) c = (char)tolower((unsigned char)c);
        if (v.size() >= 2 && v.front() == '"' && v.back() == '"') v = v.substr(1, v.size() - 2);
        m[k] = v;
    }
    string q;
    getline(cin, q);
    q = trim(q);
    for (auto &c : q) c = (char)tolower((unsigned char)c);
    auto it = m.find(q);
    cout << (it == m.end() ? string("MISSING") : it->second) << endl;
    return 0;
}

const lines = require('fs').readFileSync(0, 'utf8').split('\n');
const n = parseInt(lines[0].trim(), 10) || 0;
const m = new Map();
for (let i = 1; i <= n && i < lines.length; i++) {
  const s = lines[i].trim();
  if (!s || s.startsWith('#')) continue;
  const e = s.indexOf('=');
  if (e < 0) continue;
  const k = s.slice(0, e).trim().toLowerCase();
  let v = s.slice(e + 1).trim();
  if (v.length >= 2 && v[0] === '"' && v[v.length - 1] === '"') v = v.slice(1, -1);
  m.set(k, v);
}
const q = (lines[n + 1] || '').trim().toLowerCase();
console.log(m.has(q) ? m.get(q) : 'MISSING');
